/**
 * affiliateCommissions - immutable log of recurring C2C referral commissions.
 *
 * One row is created for each paid Stripe invoice generated by a referred user.
 * UNIQUE (stripe_invoice_id) keeps Stripe webhook handling idempotent.
 */
import {
  pgTable, serial, integer, text, timestamp, index, unique,
} from "drizzle-orm/pg-core";
import { usersTable } from "./users";
import { affiliateAccountsTable } from "./affiliateAccounts";

export const affiliateCommissionsTable = pgTable(
  "affiliate_commissions",
  {
    id:             serial("id").primaryKey(),
    affiliateId:    integer("affiliate_id").notNull().references(() => affiliateAccountsTable.id, { onDelete: "cascade" }),
    referredUserId: integer("referred_user_id").notNull().references(() => usersTable.id, { onDelete: "cascade" }),

    /** Commission amount in cents. */
    amountCents:    integer("amount_cents").notNull().default(580),

    /** Stripe invoice that generated this commission. */
    stripeInvoiceId: text("stripe_invoice_id"),

    /** Paid invoice amount before the referral commission, in cents. */
    sourceAmountCents: integer("source_amount_cents"),

    /** Percentage applied to sourceAmountCents. */
    commissionRatePct: integer("commission_rate_pct"),

    /**
     * Reporting period: YYYY-MM.
     * Kept for dashboard/report grouping, not for idempotency.
     */
    month:          text("month").notNull(),

    /**
     * applied_to: where the commission was booked once processed.
     *   locked       -> filled the one-month reserve first
     *   withdrawable -> reserve was already filled or commission overflowed
     */
    appliedTo: text("applied_to", { enum: ["locked", "withdrawable"] }),

    status: text("status", { enum: ["pending", "applied", "void"] })
      .notNull()
      .default("pending"),

    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    appliedAt: timestamp("applied_at", { withTimezone: true }),
  },
  (t) => ({
    affiliateIdx: index("aff_comm_affiliate_idx").on(t.affiliateId),
    invoiceIdx:   index("aff_comm_stripe_invoice_idx").on(t.stripeInvoiceId),
    monthIdx:     index("aff_comm_month_idx").on(t.month),
    uniqInvoice:  unique("aff_comm_stripe_invoice_unq").on(t.stripeInvoiceId),
  }),
);

export type AffiliateCommission = typeof affiliateCommissionsTable.$inferSelect;
export type InsertAffiliateCommission = typeof affiliateCommissionsTable.$inferInsert;
